#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
mkdir -p demo/static
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing TokenGuard Demo (Mode 1)..."
decode "demo/server.py" << 'B64EOF'

B64EOF
decode "demo/static/index.html" << 'B64EOF'

B64EOF
decode "demo/README.md" << 'B64EOF'

B64EOF
pip show fastapi >/dev/null 2>&1 || pip install fastapi uvicorn -q
echo ""
echo "Installed. Start:  python demo/server.py"
echo "Then: VS Code PORTS tab -> 8000 -> Open in Browser"